import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	if len(inputs) == 0 {
		return out
	}

	if workers <= 0 {
		for i, in := range inputs {
			out[i] = fn(in)
		}
		return out
	}

	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

export function groupConsecutive(values: number[]): number[][] {
  const groups: number[][] = [];
  let current: number[] | undefined;
  let last: number | undefined;

  for (const value of values) {
    if (current === undefined) {
      current = [value];
    } else if (last !== undefined && value - last === 1) {
      current.push(value);
    } else {
      groups.push(current);
      current = [value];
    }
    last = value;
  }

  if (current !== undefined) {
    groups.push(current);
  }

  return groups;
}

using System;
using System.Collections.Generic;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();
        long sumDeltas = 0;
        long count = 0;

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account))
            {
                totals[e.Account] = 0;
                running[e.Account] = new List<int>();
            }

            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);

            sumDeltas += e.Delta;
            count++;
        }

        var average = count == 0 ? 0.0 : (double)sumDeltas / count;

        return (running, totals, average);
    }
}

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager;
    }

    public void Send(string opcode, string payload)
    {
        string truncatedOpcode = opcode;

        if (truncatedOpcode != null && truncatedOpcode.Length > 8)
        {
            truncatedOpcode = truncatedOpcode.Substring(0, 8);
        }

        string frame = _networkManager.Encode(truncatedOpcode, payload);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int count = 0;

        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                count++;
            }
        }

        return count;
    }
}
